output_text:
[
  {
    "id": "no_carts_in_narrow_shelf_aisles",
    "text": "Shopping carts are prohibited in narrow shelf aisles where shelves constrain the aisle from both sides.",
    "abstraction": {
      "state_properties": {
        "narrowShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "narrowShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_enter_narrow_aisle_with_cart",
    "text": "Agents must not enter a narrow shelf aisle while still pushing a cart.",
    "abstraction": {
      "state_properties": {
        "narrowShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enterNarrowShelfAisleWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": {
            "and": [
              "hasCart",
              "narrowShelfAisle"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterNarrowShelfAisleWithCart"
    }
  },
  {
    "id": "narrow_aisle_items_cartless",
    "text": "Items located in narrow shelf aisles must be taken without holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "narrowShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "takeItemInNarrowAisle": {
          "pre": {
            "and": [
              "INTERACT",
              "narrowShelfAisle",
              "adjShelf"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "takeItemInNarrowAisle",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "retrieve_cart_after_cartless_aisle_item",
    "text": "After taking an item while away from the cart in a narrow shelf aisle, the agent must retrieve a cart before leaving the store.",
    "abstraction": {
      "state_properties": {
        "noCart": {
          "not": "hasCart"
        },
        "narrowShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "cartlessNarrowAisleItemInteraction": {
          "pre": {
            "and": [
              "INTERACT",
              "noCart",
              "narrowShelfAisle"
            ]
          },
          "post": "noCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartlessNarrowAisleItemInteraction",
      "discharge": "hasCart"
    }
  },
  {
    "id": "park_cart_only_in_wide_open_aisle",
    "text": "Carts may only be left behind in a wide open aisle or intersection, not beside shelves or inside cramped passages.",
    "abstraction": {
      "state_properties": {
        "wideOpenAisle": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                6
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "leaveCartBehind": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "leaveCartBehind",
          {
            "not": "wideOpenAisle"
          }
        ]
      }
    }
  },
  {
    "id": "open_shelf_items_with_cart",
    "text": "When an item can be taken from an open aisle rather than a narrow shelf aisle, the agent should take it while still having the cart.",
    "abstraction": {
      "state_properties": {
        "narrowShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "openShelfServicePoint": {
          "and": [
            "adjShelf",
            {
              "not": "narrowShelfAisle"
            },
            {
              "ge": [
                "freeWidthH",
                6
              ]
            }
          ]
        }
      },
      "events": {
        "openShelfInteraction": {
          "pre": {
            "and": [
              "INTERACT",
              "openShelfServicePoint"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "openShelfInteraction",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "do_not_block_shelves_with_parked_cart",
    "text": "Agents must not park or abandon a cart in a cell directly adjacent to a shelf, because it would block shelf access.",
    "abstraction": {
      "state_properties": {
        "shelfAccessCell": "adjShelf"
      },
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "parkCart",
          "shelfAccessCell"
        ]
      }
    }
  },
  {
    "id": "exit_with_cart_after_shopping",
    "text": "After obtaining a shopping cart, the agent must leave the supermarket with the cart rather than exiting without it.",
    "abstraction": {
      "state_properties": {
        "atExit": "at(11,7)",
        "noCart": {
          "not": "hasCart"
        }
      },
      "events": {
        "exitWithoutCart": {
          "pre": {
            "and": [
              "EXIT",
              "atExit",
              "noCart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exitWithoutCart"
    }
  }
]
